import psycopgconnection = psycopg.connect(    host="localhost",    port=5432,    dbname="de_lab",    user="de_user",    password="de_password",)customers = [    ("Alice", 25),    ("Bob", 31),    ("Charlie", 28),]with connection.cursor() as cursor:    cursor.execute("""        CREATE TABLE IF NOT EXISTS customers (            id SERIAL PRIMARY KEY,            name TEXT NOT NULL,            age INTEGER        )    """)    cursor.executemany(        "INSERT INTO customers (name, age) VALUES (%s, %s)",        customers,    )connection.commit()connection.close()print("Data inserted!")